// Creates (or removes) a "Claude Workspace" shortcut that opens the workspace app.
//
// Usage:
//   node tools/workspace-app/make-shortcut.mjs [--start-menu] [--remove] [--force] [--dry-run]
//
// - Default: a shortcut on the Desktop. --start-menu also adds one to the Start menu (search
//   for "Claude Workspace", or pin it to the taskbar from there).
// - The shortcut runs start-app.ps1 with a hidden PowerShell and the app icon (ui/icon.ico,
//   generated by make-icon.mjs when missing).
// - A "Claude Workspace" shortcut that points somewhere else is never replaced or removed
//   unless you add --force.
// - --dry-run prints the PowerShell it would run.
import { existsSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { icoPath, makeIco } from './make-icon.mjs';
import { encodePs, psq } from './launch.mjs';

const appDir = dirname(fileURLToPath(import.meta.url));
const root = resolve(appDir, '..', '..');
export const SHORTCUT_NAME = 'Claude Workspace.lnk';

// The PowerShell that creates or removes the shortcut in each folder ('Desktop', 'Programs').
// Prints one line per folder: "created <path>", "removed <path>", "kept <path> ..." or "none <path>".
// A shortcut counts as ours only when it starts THIS workspace's start-app.ps1. Output is UTF-8
// and errors are one plain line, not PowerShell's CLIXML.
export function shortcutScript({ action, folders, startApp, icon, workdir, force = false }) {
  const args = `-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "${startApp}"`;
  const lines = [
    "$ErrorActionPreference = 'Stop'",
    "$ProgressPreference = 'SilentlyContinue'",
    '[Console]::OutputEncoding = [Text.Encoding]::UTF8',
    'try {',
    '$shell = New-Object -ComObject WScript.Shell',
    `$force = ${force ? '$true' : '$false'}`,
    `$mine = ${psq(startApp)}`,
    `foreach ($folder in @(${folders.map(psq).join(', ')})) {`,
    `  $path = Join-Path ([Environment]::GetFolderPath($folder)) ${psq(SHORTCUT_NAME)}`,
    '  $ours = $true',
    '  if (Test-Path -LiteralPath $path) {',
    '    $old = $shell.CreateShortcut($path)',
    "    $ours = $old.Arguments.IndexOf($mine, [StringComparison]::OrdinalIgnoreCase) -ge 0",
    '  }',
    '  if (-not $ours -and -not $force) { Write-Output "kept $path (it does not start the app of this workspace; use --force)"; continue }',
  ];
  if (action === 'remove') {
    lines.push(
      '  if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path; Write-Output "removed $path" } else { Write-Output "none $path" }',
    );
  } else {
    lines.push(
      '  $s = $shell.CreateShortcut($path)',
      "  $s.TargetPath = Join-Path $env:SystemRoot 'System32\\WindowsPowerShell\\v1.0\\powershell.exe'",
      `  $s.Arguments = ${psq(args)}`,
      `  $s.WorkingDirectory = ${psq(workdir)}`,
      `  $s.IconLocation = ${psq(`${icon},0`)}`,
      "  $s.Description = 'Claude Workspace: dashboard, projects, agents and images'",
      '  $s.WindowStyle = 7',
      '  $s.Save()',
      '  Write-Output "created $path"',
    );
  }
  lines.push('}', '} catch {', '  [Console]::Error.WriteLine($_.Exception.Message)', '  exit 1', '}');
  return lines.join('\n');
}

function main(argv) {
  const flags = new Set(argv);
  for (const f of flags) {
    if (!['--start-menu', '--remove', '--force', '--dry-run', '-h', '--help'].includes(f)) {
      console.error(`make-shortcut: unknown option ${f}`);
      process.exit(1);
    }
  }
  if (flags.has('-h') || flags.has('--help')) {
    console.log('Usage: node tools/workspace-app/make-shortcut.mjs [--start-menu] [--remove] [--force] [--dry-run]');
    return;
  }
  if (process.platform !== 'win32') {
    console.error('make-shortcut: Windows shortcuts can only be made on Windows.');
    process.exit(1);
  }
  const action = flags.has('--remove') ? 'remove' : 'create';
  const folders = flags.has('--start-menu') ? ['Desktop', 'Programs'] : ['Desktop'];
  const script = shortcutScript({
    action, folders, force: flags.has('--force'),
    startApp: join(appDir, 'start-app.ps1'), icon: icoPath, workdir: root,
  });
  if (flags.has('--dry-run')) { console.log(script); return; }
  if (action === 'create' && !existsSync(icoPath)) writeFileSync(icoPath, makeIco());
  const r = spawnSync('powershell.exe', ['-NoProfile', '-NonInteractive', '-EncodedCommand', encodePs(script)], { encoding: 'utf8', windowsHide: true });
  if (r.status !== 0) {
    console.error(`make-shortcut: PowerShell failed: ${(r.stderr || r.error || '').toString().trim()}`);
    process.exit(1);
  }
  process.stdout.write(r.stdout);
  if (action === 'create') console.log('Double-click "Claude Workspace" to open the app. Remove it with: node tools/workspace-app/make-shortcut.mjs --remove');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) main(process.argv.slice(2));
